package com.quincaisoft.workforce.application;
import com.quincaisoft.workforce.api.WorkforceService;
import java.util.List;

/** Pure renderer of the immutable payslip snapshot. Dynamic content is always escaped. */
public final class WorkforceRendering {
 private WorkforceRendering() {}
 static String escape(String value){if(value==null)return "";return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 public static String html(WorkforceService.Payslip p,List<WorkforceService.Deduction> deductions){
  StringBuilder rows=new StringBuilder();for(var d:deductions)rows.append("<tr><td>").append(escape(d.code())).append("</td><td>").append(escape(d.label())).append("</td><td>").append(escape(d.amountXaf())).append("</td><td>").append(escape(d.policyReference())).append("</td></tr>");
  return "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>QuincaiSoft payslip</title><style>body{font:14px system-ui,sans-serif;color:#162238;margin:32px;max-width:900px}h1{border-bottom:3px solid #1595E6;padding-bottom:12px}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{border:1px solid #E3E8F0;padding:8px;text-align:left}th{background:#F7FAFD}.notice{border:1px solid #E3E8F0;padding:12px}@media print{body{margin:12mm}thead{display:table-header-group}tr{break-inside:avoid}}</style></head><body><h1>QuincaiSoft · Payslip</h1><p>Employee: "+escape(p.employeeName())+" · "+escape(p.employeeNumber())+"</p><p>Period: "+p.periodStart()+" to "+p.periodEnd()+" · Business date: "+p.businessDate()+"</p><p>Record: "+p.id()+" · Version: "+escape(p.version())+" · Status: "+escape(p.status())+"</p><table><thead><tr><th>Gross XAF</th><th>Deductions XAF</th><th>Net XAF</th></tr></thead><tbody><tr><td>"+escape(p.grossXaf())+"</td><td>"+escape(p.deductionXaf())+"</td><td>"+escape(p.netXaf())+"</td></tr></tbody></table><table><thead><tr><th>Code</th><th>Deduction</th><th>XAF</th><th>Policy reference</th></tr></thead><tbody>"+rows+"</tbody></table><p>Calculation policy: "+escape(p.calculationPolicy())+"</p><p>Accrual journal: "+(p.journalId()==null?"Not posted":p.journalId())+"</p><p class=\"notice\">This document records reviewed payroll amounts. It does not certify statutory calculations or external provider settlement. ACCRUED_UNPAID is an unpaid liability; PAID_RECORDED refers to independently approved bank evidence recorded in the system.</p></body></html>";
 }
 private static String cell(String value){String v=value==null?"":value;if(!v.isEmpty()&&"=+-@\t\r\n".indexOf(v.charAt(0))>=0)v="'"+v;return "\""+v.replace("\"","\"\"")+"\"";}
 public static String csv(List<WorkforceService.Payslip> rows){var out=new StringBuilder("id,employee_number,employee_name,period_start,period_end,business_date,gross_xaf,deduction_xaf,net_xaf,status,calculation_policy\r\n");for(var p:rows){out.append(String.join(",",List.of(cell(p.id().toString()),cell(p.employeeNumber()),cell(p.employeeName()),cell(p.periodStart().toString()),cell(p.periodEnd().toString()),cell(p.businessDate().toString()),cell(p.grossXaf()),cell(p.deductionXaf()),cell(p.netXaf()),cell(p.status()),cell(p.calculationPolicy())))).append("\r\n");}return out.toString();}
}
